                ],
                [
                    'id' => 'g2',
                    'title' => 'Unit types and sizes',
                    'text' => 'From a 55 m² studio to a standalone villa above 400 m². Apartments are the most in demand, and the townhouse is the middle choice between an apartment and a villa.',
                ],
